import { useState } from "react";
import { CurrencyContext } from "./CurrencyContext.jsx";
import { CartProvider } from "./CartContext.jsx";
import Header from "./Header.jsx";
import ProductList from "./ProductList.jsx";
import Cart from "./Cart.jsx";
import Modal from "./Modal.jsx";
import CheckoutForm from "./CheckoutForm.jsx";

export default function App({ products }) {
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);
  const closeCheckout = () => setIsCheckoutOpen(false);

  return (
    <CurrencyContext value="USD">
      <CartProvider>
        <Header onCheckout={() => setIsCheckoutOpen(true)} />
        <ProductList products={products} />
        <Cart />
        {isCheckoutOpen && (
          <Modal onClose={closeCheckout}>
            <CheckoutForm onSubmitted={closeCheckout} />
          </Modal>
        )}
      </CartProvider>
    </CurrencyContext>
  );
}

import { useCart } from "./CartContext.jsx";
import { formatPrice, useCurrency } from "./CurrencyContext.jsx";

const TAX_RATE = 0.1;

export default function Cart() {
  const { items, remove, setQuantity } = useCart();
  const currency = useCurrency();

  const subtotal = items.reduce((sum, item) => sum + item.price * item.quantity, 0);
  const tax = subtotal * TAX_RATE;
  const total = subtotal + tax;

  return (
    <section>
      <h2>Cart</h2>
      {items.length === 0 ? (
        <p>Your cart is empty</p>
      ) : (
        <ul>
          {items.map((item) => (
            <li key={item.id}>
              <span>{item.name}</span>
              <input
                type="number"
                min="1"
                aria-label={`Quantity of ${item.name}`}
                value={item.quantity}
                onChange={(event) => setQuantity(item.id, Number(event.target.value))}
              />
              <button type="button" onClick={() => remove(item.id)}>
                Remove
              </button>
            </li>
          ))}
        </ul>
      )}
      <dl>
        <dt>Subtotal</dt>
        <dd>{formatPrice(subtotal, currency)}</dd>
        <dt>Tax (10%)</dt>
        <dd>{formatPrice(tax, currency)}</dd>
        <dt>Total</dt>
        <dd>{formatPrice(total, currency)}</dd>
      </dl>
    </section>
  );
}

import { createContext, useContext, useMemo, useReducer } from "react";

const CartContext = createContext(null);

function cartReducer(items, action) {
  switch (action.type) {
    case "add": {
      const existing = items.find((item) => item.id === action.product.id);
      if (existing) {
        return items.map((item) =>
          item.id === action.product.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...items, { ...action.product, quantity: 1 }];
    }
    case "remove":
      return items.filter((item) => item.id !== action.id);
    case "setQuantity":
      if (action.quantity <= 0) {
        return items.filter((item) => item.id !== action.id);
      }
      return items.map((item) =>
        item.id === action.id ? { ...item, quantity: action.quantity } : item
      );
    case "clear":
      return [];
    default:
      throw new Error(`Unknown action: ${action.type}`);
  }
}

export function CartProvider({ children }) {
  const [items, dispatch] = useReducer(cartReducer, []);

  const value = useMemo(
    () => ({
      items,
      count: items.reduce((sum, item) => sum + item.quantity, 0),
      add: (product) => dispatch({ type: "add", product }),
      remove: (id) => dispatch({ type: "remove", id }),
      setQuantity: (id, quantity) => dispatch({ type: "setQuantity", id, quantity }),
      clear: () => dispatch({ type: "clear" }),
    }),
    [items]
  );

  return <CartContext value={value}>{children}</CartContext>;
}

export function useCart() {
  const context = useContext(CartContext);
  if (!context) {
    throw new Error("useCart must be used within a CartProvider");
  }
  return context;
}

import { useState } from "react";
import { useCart } from "./CartContext.jsx";

export default function CheckoutForm({ onSubmitted }) {
  const { clear } = useCart();
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");

  const nameError = name.trim() ? "" : "Name is required";
  const emailError = email.includes("@") ? "" : "Email must contain @";
  const isValid = !nameError && !emailError;

  function handleSubmit(event) {
    event.preventDefault();
    if (!isValid) return;
    clear();
    onSubmitted();
  }

  return (
    <form onSubmit={handleSubmit} noValidate>
      <label>
        Name
        <input value={name} onChange={(event) => setName(event.target.value)} />
      </label>
      {nameError && <p role="alert">{nameError}</p>}
      <label>
        Email
        <input type="email" value={email} onChange={(event) => setEmail(event.target.value)} />
      </label>
      {emailError && <p role="alert">{emailError}</p>}
      <button type="submit" disabled={!isValid}>
        Place order
      </button>
    </form>
  );
}

import { createContext, useContext } from "react";

export const CurrencyContext = createContext("USD");

export function useCurrency() {
  return useContext(CurrencyContext);
}

export function formatPrice(amount, currency) {
  return new Intl.NumberFormat("en-US", { style: "currency", currency }).format(amount);
}

import { useCart } from "./CartContext.jsx";

export default function Header({ onCheckout }) {
  const { count } = useCart();

  return (
    <header>
      <h1>Shop</h1>
      <span>Cart: {count} {count === 1 ? "item" : "items"}</span>
      <button type="button" onClick={onCheckout}>
        Checkout
      </button>
    </header>
  );
}

import { useEffect } from "react";

export default function Modal({ onClose, children }) {
  useEffect(() => {
    function handleKeyDown(event) {
      if (event.key === "Escape") {
        onClose();
      }
    }
    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [onClose]);

  return (
    <div role="dialog" aria-modal="true">
      <button type="button" aria-label="Close" onClick={onClose}>
        ×
      </button>
      {children}
    </div>
  );
}

import { formatPrice, useCurrency } from "./CurrencyContext.jsx";

export default function ProductItem({ product, onAdd }) {
  const currency = useCurrency();

  return (
    <li>
      <span>{product.name}</span>
      <span>{formatPrice(product.price, currency)}</span>
      <button type="button" onClick={() => onAdd(product)}>
        Add
      </button>
    </li>
  );
}

import { useMemo, useState } from "react";
import { useCart } from "./CartContext.jsx";
import SearchBox from "./SearchBox.jsx";
import ProductItem from "./ProductItem.jsx";

const ALL_CATEGORIES = "all";

export default function ProductList({ products }) {
  const { add } = useCart();
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState(ALL_CATEGORIES);

  const categories = useMemo(
    () => [...new Set(products.map((product) => product.category))],
    [products]
  );

  const normalizedQuery = query.trim().toLowerCase();
  const visibleProducts = products.filter(
    (product) =>
      (category === ALL_CATEGORIES || product.category === category) &&
      product.name.toLowerCase().includes(normalizedQuery)
  );

  return (
    <section>
      <SearchBox onSearch={setQuery} />
      <select
        aria-label="Category"
        value={category}
        onChange={(event) => setCategory(event.target.value)}
      >
        <option value={ALL_CATEGORIES}>All categories</option>
        {categories.map((name) => (
          <option key={name} value={name}>
            {name}
          </option>
        ))}
      </select>
      {visibleProducts.length === 0 ? (
        <p>No products</p>
      ) : (
        <ul>
          {visibleProducts.map((product) => (
            <ProductItem key={product.id} product={product} onAdd={add} />
          ))}
        </ul>
      )}
    </section>
  );
}

import { useEffect, useState } from "react";

export default function SearchBox({ onSearch }) {
  const [value, setValue] = useState("");

  useEffect(() => {
    const timer = setTimeout(() => onSearch(value), 300);
    return () => clearTimeout(timer);
  }, [value, onSearch]);

  return (
    <input
      type="search"
      placeholder="Search products"
      aria-label="Search products"
      value={value}
      onChange={(event) => setValue(event.target.value)}
    />
  );
}
